import{_ as l,a0 as o,w as p,s as r,ao as d,I as i,x as t,a1 as s,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"在 CentOS 7 中安装并使用自动化工具 Ansible | LCTT x X-CMD","titleTemplate":false,"description":"在 CentOS 7 中安装并使用自动化工具 Ansible | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 CentOS 7 中安装并使用自动化工具 Ansible | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 CentOS 7 中安装并使用自动化工具 Ansible | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150930 Install and use Ansible (Automation Tool) in CentOS 7","title":"在 CentOS 7 中安装并使用自动化工具 Ansible","tag":"201510","desc":""},"relativePath":"201510/20150930 Install and use Ansible (Automation Tool) in CentOS 7.md","filePath":"[post].md"}'),m={name:"201510/20150930 Install and use Ansible (Automation Tool) in CentOS 7.md"};function b(u,e,c,h,g,w){const n=o("Link");return p(),r("div",null,[e[13]||(e[13]=d(`<h1 id="在-centos-7-中安装并使用自动化工具-ansible" tabindex="-1">在 CentOS 7 中安装并使用自动化工具 Ansible <a class="header-anchor" href="#在-centos-7-中安装并使用自动化工具-ansible" aria-label="Permalink to “在 CentOS 7 中安装并使用自动化工具 Ansible”">​</a></h1><p>Ansible是一款为类Unix系统开发的自由开源的配置和自动化工具。它用Python写成，类似于Chef和Puppet，但是有一个不同和优点是我们不需要在节点中安装任何客户端。它使用SSH来和节点进行通信。</p><p>本篇中我们将在CentOS 7上安装并配置Ansible，并且尝试管理两个节点。</p><ul><li><p><strong>Ansible 服务端</strong> – ansible.linuxtechi.com ( 192.168.1.15 )</p></li><li><p><strong>节点</strong> – 192.168.1.9 , 192.168.1.10</p></li></ul><h3 id="第一步-设置epel仓库" tabindex="-1">第一步： 设置EPEL仓库 <a class="header-anchor" href="#第一步-设置epel仓库" aria-label="Permalink to “第一步： 设置EPEL仓库”">​</a></h3><p>Ansible仓库默认不在yum仓库中，因此我们需要使用下面的命令启用epel仓库。</p><pre><code>[root@ansible ~]# rpm -iUvh http://dl.fedoraproject.org/pub/epel/7/x86_64/e/epel-release-7-5.noarch.rpm
</code></pre><h3 id="第二步-使用yum安装ansible" tabindex="-1">第二步： 使用yum安装Ansible <a class="header-anchor" href="#第二步-使用yum安装ansible" aria-label="Permalink to “第二步： 使用yum安装Ansible”">​</a></h3><pre><code>[root@ansible ~]# yum install ansible
</code></pre><p>安装完成后，检查ansible版本：</p><pre><code>[root@ansible ~]# ansible --version
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ansible-version.jpg" alt="ansible-version"></p><h3 id="第三步-设置用于节点鉴权的ssh密钥" tabindex="-1">第三步： 设置用于节点鉴权的SSH密钥 <a class="header-anchor" href="#第三步-设置用于节点鉴权的ssh密钥" aria-label="Permalink to “第三步： 设置用于节点鉴权的SSH密钥”">​</a></h3><p>在Ansible服务端生成密钥，并且复制公钥到节点中。</p><pre><code>root@ansible ~]# ssh-keygen
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ssh-keygen.jpg" alt="ssh-keygen"></p><p>使用ssh-copy-id命令来复制Ansible公钥到节点中。</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ssh-copy-id-command.jpg" alt="ssh-copy-id-command"></p><h3 id="第四步-为ansible定义节点的清单" tabindex="-1">第四步：为Ansible定义节点的清单 <a class="header-anchor" href="#第四步-为ansible定义节点的清单" aria-label="Permalink to “第四步：为Ansible定义节点的清单”">​</a></h3><p>文件 <code>/etc/ansible/hosts</code> 维护着Ansible中服务器的清单。</p><pre><code>[root@ansible ~]# vi /etc/ansible/hosts
[test-servers]
192.168.1.9
192.168.1.10
</code></pre><p>保存并退出文件。</p><p>主机文件示例如下：</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ansible-host.jpg" alt="ansible-host"></p><h3 id="第五步-尝试在ansible服务端运行命令" tabindex="-1">第五步：尝试在Ansible服务端运行命令 <a class="header-anchor" href="#第五步-尝试在ansible服务端运行命令" aria-label="Permalink to “第五步：尝试在Ansible服务端运行命令”">​</a></h3><p>使用ping检查‘test-servers’或者ansible节点的连通性。</p><pre><code>[root@ansible ~]# ansible -m ping &#39;test-servers&#39;
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ansible-ping.jpg" alt="ansible-ping"></p><h4 id="执行shell命令" tabindex="-1">执行shell命令 <a class="header-anchor" href="#执行shell命令" aria-label="Permalink to “执行shell命令”">​</a></h4><p><strong>例子1：检查Ansible节点的运行时间（uptime）</strong></p><pre><code>[root@ansible ~]# ansible -m command -a &quot;uptime&quot; &#39;test-servers&#39;
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/ansible-uptime.jpg" alt="ansible-uptime"></p><p><strong>例子2：检查节点的内核版本</strong></p><pre><code>[root@ansible ~]# ansible -m command -a &quot;uname -r&quot; &#39;test-servers&#39;
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/kernel-version-ansible.jpg" alt="kernel-version-ansible"></p><p><strong>例子3：给节点增加用户</strong></p><pre><code>[root@ansible ~]# ansible -m command -a &quot;useradd mark&quot; &#39;test-servers&#39;
[root@ansible ~]# ansible -m command -a &quot;grep mark /etc/passwd&quot; &#39;test-servers&#39;
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/useradd-ansible.jpg" alt="useradd-ansible"></p><p><strong>例子4：重定向输出到文件中</strong></p><pre><code>[root@ansible ~]# ansible -m command -a &quot;df -Th&quot; &#39;test-servers&#39; &gt; /tmp/command-output.txt
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/09/redirecting-output-ansible.jpg" alt="redirecting-output-ansible"></p><hr>`,42)),i("p",null,[e[1]||(e[1]=t("via: ",-1)),s(n,{href:"http://www.linuxtechi.com/install-and-use-ansible-in-centos-7/"},{default:a(()=>[...e[0]||(e[0]=[t("http://www.linuxtechi.com/install-and-use-ansible-in-centos-7/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=t("作者：",-1)),s(n,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...e[2]||(e[2]=[t("Pradeep Kumar",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:a(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=t("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创编译，",-1)),s(n,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const C=l(m,[["render",b]]);export{f as __pageData,C as default};
